const res = await fetch("https://api.kmail.kchat.dev/api/v1/signup", {
  method: "POST",
  headers: { "Content-Type": "application/json" },
  body: JSON.stringify({ email: "founder@acme.com", org_name: "Acme", plan: "pro" }),
});
const { checkout_url } = await res.json();
window.location = checkout_url; // redirect to Stripe Checkout

const res = await fetch("https://api.kmail.kchat.dev/api/v1/tenants", {
  headers: { Authorization: `Bearer ${process.env.KMAIL_TOKEN}` },
});
if (!res.ok) throw new Error(`HTTP ${res.status}`);
console.log(await res.json());
